package cn.zhuatech.fsm.controller; import cn.zhuatech.fsm.common.ApiResponse; import cn.zhuatech.fsm.dto.FsmDto.*; import cn.zhuatech.fsm.service.FsmService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('FIELD_TECHNICIAN','ADMIN')") public class FieldTechnicianController {private final FsmService service;public FieldTechnicianController(FsmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
